2704: function drawBriefMap(opNum,cfg){
2705:   const c=$('briefMap'), g=c.getContext('2d');
2706:   const w=c.width, h=c.height;
2707:   const rnd=mulberry32(0x51a7 ^ (opNum*7717));
2708:   g.clearRect(0,0,w,h);
2709:   g.fillStyle='#0a130c'; g.fillRect(0,0,w,h);
2710:   // grid
2711:   g.strokeStyle='rgba(145,170,130,.10)'; g.lineWidth=1;
2712:   for (let x=0;x<w;x+=26){ g.beginPath(); g.moveTo(x,0); g.lineTo(x,h); g.stroke(); }
2713:   for (let y=0;y<h;y+=26){ g.beginPath(); g.moveTo(0,y); g.lineTo(w,y); g.stroke(); }
2714:   // river
2715:   g.strokeStyle='rgba(103,151,150,.5)'; g.lineWidth=7;
2716:   g.beginPath(); g.moveTo(120,0);
2717:   for (let y=0;y<=h;y+=20) g.lineTo(120+40*Math.sin(y*0.023+1)+8*Math.sin(y*0.07),y);
2718:   g.stroke();
2719:   g.strokeStyle='rgba(170,200,190,.25)'; g.lineWidth=1.5; g.stroke();
2720:   // road
2721:   g.strokeStyle='rgba(180,160,110,.38)'; g.lineWidth=2;
2722:   g.beginPath(); g.moveTo(30,h); g.quadraticCurveTo(260,170,500,30); g.stroke();
2723:   // contours
2724:   for (let i=0;i<11;i++){
2725:     const cx=20+rnd()*w, cy=20+rnd()*h, rx=30+rnd()*90, ry=14+rnd()*45, rot=rnd()*Math.PI;
2726:     g.strokeStyle=`rgba(133,157,109,${0.10+rnd()*0.10})`; g.lineWidth=1;
2727:     g.beginPath(); g.ellipse(cx,cy,rx,ry,rot,0,TAU); g.stroke();
2728:     if (rnd()>0.35){ g.beginPath(); g.ellipse(cx,cy,rx*0.65,ry*0.62,rot,0,TAU); g.stroke(); }
2729:   }
2730:   // target sectors (approximate)
2731:   const n=Math.min(cfg.targets,8);
2732:   for (let i=0;i<n;i++){
2733:     const tx=250+ (i-(n-1)/2)*34 + (rnd()-0.5)*26;
2734:     const ty=80 + rnd()*130;
2735:     g.strokeStyle='rgba(220,104,80,.7)'; g.lineWidth=1;
2736:     g.beginPath(); g.moveTo(tx,ty-5); g.lineTo(tx+5,ty+4); g.lineTo(tx-5,ty+4); g.closePath(); g.stroke();
2737:     if (i===0){ g.strokeStyle='rgba(220,104,80,.35)'; g.beginPath(); g.arc(tx,ty,12,0,TAU); g.stroke(); }
2738:   }
2739:   // observer position
2740:   g.fillStyle='#e5b45b'; g.beginPath(); g.arc(56,238,4,0,TAU); g.fill();
2741:   g.strokeStyle='rgba(229,180,91,.5)'; g.beginPath(); g.arc(56,238,10,0,TAU); g.stroke();
2742:   g.fillStyle='rgba(211,225,194,.6)'; g.font='8px ui-monospace,monospace';
2743:   g.fillText('OBSERVER',70,241);
2744:   g.fillText('SECTOR 7',24,26);
2745:   g.fillStyle='rgba(220,104,80,.85)'; g.fillText('HOSTILE',250,60);
2746:   g.fillStyle='rgba(140,170,130,.4)'; g.font='7px ui-monospace,monospace';
2747:   g.fillText('APPROACH',360,250);
2748: }
